import re

def split_fields(line):
    def match():
        nonlocal pos
        if pos >= len(line):
            raise StopIteration
        token = ""
        quotes = 0
        while True:
            if pos == len(line):
                if quotes != 0:
                    raise ValueError("Unmatched quotes")
                yield token.strip('"')
                raise StopIteration
            elif line[pos] == '"':
                quotes += 1
                token += line[pos]
                pos += 1
            elif line[pos] == ',' and quotes % 2 == 0:
                pos += 1
                yield token.strip('"')
                token = ""
            else:
                token += line[pos]
                pos += 1

    pos = 0
    return list(match())
