import re

def split_fields(line):
    def unescape_quotes(match):
        return match.group(1).replace('""', '"')

    result = []
    field = ''
    in_quotes = False
    i = 0

    while i < len(line):
        if line[i] == '"':
            if in_quotes:
                if i + 1 < len(line) and line[i + 1] == '"':
                    field += '""'
                    i += 2
                else:
                    result.append(field)
                    field = ''
                    in_quotes = False
                    i += 1
            else:
                in_quotes = True
                i += 1
        elif line[i] == ',' and not in_quotes:
            result.append(field)
            field = ''
            i += 1
        else:
            field += line[i]
            i += 1

    if in_quotes:
        raise ValueError("Unmatched double quote in CSV line")

    result.append(field)
    return re.sub(r'(["\'])(?:(?=(?:[^"]*"[^"]*")*[^"]*$).)*?\1', unescape_quotes, line).split(',')
