    fields = []
    in_quotes = False
    field = []

    i = 0
    while i < len(line):
        if line[i] == '"':
            if in_quotes:
                if i + 1 < len(line) and line[i + 1] == '"':
                    field.append('"')
                    i += 2
                else:
                    in_quotes = False
                    i += 1
            else:
                in_quotes = True
                i += 1
        else:
            if in_quotes:
                field.append(line[i])
                i += 1
            else:
                if line[i] == ',':
                    fields.append(''.join(field))
                    field = []
                    i += 1
                else:
                    field.append(line[i])
                    i += 1

    if field:
        fields.append(''.join(field))

    return fields
