def split_fields(line):
    fields = []
    field = ''
    in_quotes = False
    i = 0
    n = len(line)

    while i < n:
        if line[i] == '"':
            if i + 1 < n and line[i + 1] == '"':
                field += '"'
                i += 2
            elif in_quotes:
                in_quotes = False
                i += 1
            else:
                in_quotes = True
                i += 1
        elif line[i] == ',' and not in_quotes:
            fields.append(field)
            field = ''
            i += 1
        else:
            field += line[i]
            i += 1

    if field:
        fields.append(field)

    return fields
