def split_fields(line):
    fields = []
    field = ""
    in_quotes = False
    i = 0
    while i < len(line):
        if line[i] == '"':
            if in_quotes:
                if i + 1 < len(line) and line[i + 1] == '"':
                    field += '"'
                    i += 2
                else:
                    in_quotes = False
                    i += 1
            else:
                in_quotes = True
                i += 1
        elif line[i] == ',' and not in_quotes:
            fields.append(field)
            field = ""
            i += 1
        else:
            field += line[i]
            i += 1
    if in_quotes:
        raise ValueError(" Unterminated quoted field")
    fields.append(field)
    return fields
```

