def split_fields(line):
    import io
    fields = []
    field = io.StringIO()
    in_quotes = False
    i = 0
    while i < len(line):
        char = line[i]
        i += 1
        if char == '"':
            if in_quotes:
                if i < len(line) and line[i] == '"':
                    field.write('"')
                    i += 1
                else:
                    in_quotes = False
            else:
                in_quotes = True
        elif char == ',' and not in_quotes:
            fields.append(field.getvalue())
            field = io.StringIO()
        else:
            field.write(char)
    if in_quotes:
        raise ValueError("Unfinished quoted field at end of line")
    fields.append(field.getvalue())
    return fields
