def split_fields(line):
    result = []
    regex = re.compile(r'([^\"]*?)(?:\"([^\"]*?)\")*')
    fields = regex.split(line)
    for i, field in enumerate(fields):
        if i % 2 == 0:
            result.append(field.replace('""', '"'))
        else:
            result.append(field.strip('"'))
    return result
